create table if not exists public.orders(id bigint generated by default as identity primary key,product text not null,name text not null,phone text not null,city text not null,district text not null,address text not null,request_no text not null check(request_no ~ '^[0-9]{17}$'),request_date text not null,request_code text not null check(request_code ~ '^[0-9]{3}$'),created_at timestamptz not null default now()); alter table public.orders enable row level security;